const body = $input.first().json.body || $input.first().json;
const meta = body.youtube_metadata || {};
return [{
  json: {
    post_id: body.post_id,
    user_id: body.user_id,
    platform: body.platform || 'youtube',
    media_type: String(body.media_type || 'VIDEO').toUpperCase(),
    media_urls: body.media_urls || [],
    media_size_bytes: body.media_size_bytes || null,
    title: meta.title || '',
    description: meta.description || '',
    privacy: meta.privacy || 'private',
    made_for_kids: meta.made_for_kids === true,
    tags: Array.isArray(meta.tags) ? meta.tags : [],
    category_id: String(meta.category_id || '22'),
    access_token: body.token && body.token.access_token,
    callback_url: body.callback_url
  }
}];

const req = $('Parse Request').first().json;
return [{
  json: {
    post_id: req.post_id,
    platform: 'youtube',
    status: 'FAILED',
    platform_post_id: null,
    error: 'Invalid payload: media_urls, youtube_metadata.title and token.access_token are required',
    callback_url: req.callback_url
  }
}];

// YouTube returns the video resource as soon as the bytes land —
// status.uploadStatus is still 'uploaded' here, not 'processed'. SUCCESS only
// means "upload accepted"; the backend's video-status poller decides when
// the post is actually PUBLISHED (or FAILED, e.g. rejected as a duplicate).
const req = $('Parse Request').first().json;
return [{
  json: {
    post_id: req.post_id,
    platform: 'youtube',
    status: 'SUCCESS',
    platform_post_id: $json.id,
    error: null,
    callback_url: req.callback_url
  }
}];

// Reached via the error output of any API/Code node. Runs once for all
// items so a failed carousel child sends a single FAILED callback.
const req = $('Parse Request').first().json;
const err = $input.first().json.error;
const msg = (typeof err === 'string' ? err : err?.message) || 'Unknown error';
const detail = typeof err === 'object' && err?.description ? ' - ' + err.description : '';
return [{
  json: {
    post_id: req.post_id,
    platform: 'youtube',
    status: 'FAILED',
    platform_post_id: null,
    error: msg + detail + ' (node: ' + $prevNode.name + ')',
    callback_url: req.callback_url
  }
}];

// ---- Relay helpers (same copy in every relay Code node) ----
// Raw http(s), not this.helpers.httpRequest: the helper corrupts binary
// bodies inside n8n 2.x's task runner, and there's no fetch there. Needs
// NODE_FUNCTION_ALLOW_BUILTIN=https on the n8n container (websitePlan.md §15).
const REQUEST_TIMEOUT_MS = 120000;
const MAX_ATTEMPTS = 3;

function send(method, url, headers, body, redirectsLeft = 5) {
  return new Promise((resolve, reject) => {
    const lib = url.startsWith('http:') ? require('http') : require('https');
    const req = lib.request(url, { method, headers }, (res) => {
      // 308 is YouTube's "resume incomplete", not a redirect.
      if (res.statusCode >= 300 && res.statusCode < 400 && res.statusCode !== 308 && res.headers.location && redirectsLeft > 0) {
        res.resume();
        resolve(send(method, new URL(res.headers.location, url).toString(), headers, body, redirectsLeft - 1));
        return;
      }
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks) }));
      res.on('error', reject);
    });
    req.setTimeout(REQUEST_TIMEOUT_MS, () => {
      const err = new Error('Request timed out (ETIMEDOUT)');
      err.code = 'ETIMEDOUT';
      req.destroy(err);
    });
    req.on('error', reject);
    req.end(body);
  });
}

// "<status> - <body>", the shape lib/platform-error.ts parses.
function httpError(res, prefix = '') {
  const err = new Error(prefix + res.status + ' - ' + res.body.toString('utf8').slice(0, 1000));
  err.status = res.status;
  return err;
}

const isRetryable = (err) => err.code !== undefined || err.status === 429 || err.status >= 500;
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function withRetry(fn) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt >= MAX_ATTEMPTS || !isRetryable(err)) throw err;
      await sleep(1000 * 3 ** (attempt - 1));
    }
  }
}

// One byte range of the S3 object (inclusive).
async function readRange(url, first, last) {
  const res = await send('GET', url, { Range: 'bytes=' + first + '-' + last });
  const expected = last - first + 1;
  if (res.status !== 206 || res.body.length !== expected) {
    if (res.status === 206 || res.status === 200) {
      throw new Error('Reading the media file failed: got ' + res.body.length + ' bytes for a ' + expected + '-byte range');
    }
    throw httpError(res, 'Reading the media file failed: ');
  }
  return { body: res.body, contentType: res.headers['content-type'] || 'video/mp4' };
}

// The object's total size, from a one-byte ranged GET (HEAD is refused on a
// GET-presigned URL).
async function probeSize(url) {
  const res = await send('GET', url, { Range: 'bytes=0-0' });
  const total = Number(String(res.headers['content-range'] || '').split('/')[1]);
  if (res.status !== 206 || !total) throw httpError(res, 'Reading the media file failed: ');
  return total;
}

// ---- This node ----
// The resumable session is opened with the total size (X-Upload-Content-Length)
// and every chunk's Content-Range needs it. The backend sends it for uploaded
// media; older posts with a plain URL are probed.
const req = $input.first().json;
const known = Number(req.media_size_bytes);
const size = known > 0 ? known : await withRetry(() => probeSize(req.media_urls[0]));
return [{ json: { ...req, size_bytes: size } }];

