// ---- This node ----
// websitePlan.md §15.5. Chunked resumable upload: each chunk is a ranged GET
// from S3 PUT to the session with Content-Range, the next chunk is read
// while the current one uploads (at most 2 chunks in memory). YouTube answers
// 308 with how much it has, and that offset (not ours) decides the next
// chunk. After a dropped connection or a 5xx, ask the session how much it
// committed and carry on from there instead of starting over.
const CHUNK_BYTES = 16 * 1024 * 1024; // must be a multiple of 256 KiB
const MAX_RESUMES = 5;

const req = $('Parse Request').first().json;
const total = $('YT Probe Video Size').first().json.size_bytes;
const session = $json.headers.location || $json.headers.Location;
const sourceUrl = req.media_urls[0];

// "bytes=0-1048575" → 1048576; no Range header means nothing stored yet.
const committedFrom = (res) => {
  const match = /bytes=\d+-(\d+)/.exec(String(res.headers.range || ''));
  return match ? Number(match[1]) + 1 : 0;
};
const finished = (res) => res.status === 200 || res.status === 201;

async function sessionStatus() {
  const res = await send('PUT', session, { 'Content-Length': 0, 'Content-Range': 'bytes */' + total });
  if (finished(res)) return { video: JSON.parse(res.body.toString('utf8')) };
  if (res.status === 308) return { offset: committedFrom(res) };
  throw httpError(res);
}

const readChunk = (first) => {
  const last = Math.min(first + CHUNK_BYTES, total) - 1;
  const promise = withRetry(() => readRange(sourceUrl, first, last));
  promise.catch(() => {}); // awaited later; don't count as unhandled meanwhile
  return { first, promise };
};

let offset = 0;
let resumes = 0;
let pending = readChunk(0);
let video = null;
while (!video) {
  const chunk = pending.first === offset ? await pending.promise : await readChunk(offset).promise;
  const last = offset + chunk.body.length - 1;
  pending = last + 1 < total ? readChunk(last + 1) : { first: -1 };

  let res = null;
  let failure = null;
  try {
    res = await send('PUT', session, {
      'Content-Length': chunk.body.length,
      'Content-Range': 'bytes ' + offset + '-' + last + '/' + total,
    }, chunk.body);
    if (finished(res)) {
      video = JSON.parse(res.body.toString('utf8'));
      break;
    }
    if (res.status === 308) {
      offset = committedFrom(res);
      continue;
    }
    failure = httpError(res);
  } catch (err) {
    failure = err;
  }
  if (!isRetryable(failure) || ++resumes > MAX_RESUMES) throw failure;
  await sleep(1000 * 2 ** resumes);
  const status = await withRetry(sessionStatus);
  if (status.video) video = status.video;
  else offset = status.offset;
}

return [{ json: video }];
